119	  id: string;
120	  name?: string;
121	  color?: TagColor;
122	}
123	
124	export type WorkspaceEditRefusal =
125	  | "read-only"
126	  | "unknown"
127	  | "invalid-name"
128	  | "invalid-color"
129	  | "name-taken"
130	  | "not-writable";
131	
132	/** `workspaces:edit`: rename and/or recolor. */
133	export type WorkspaceEditResult =
134	  | {
135	      ok: true;
136	      workspace: WorkspaceView;
137	      /**
138	       * False for a workspace that is not connected: the change is in the registry and reaches
139	       * the folder's `identity.json` when it is reconnected.
140	       */
141	      savedToFolder: boolean;
142	    }
143	  | { ok: false; reason: WorkspaceEditRefusal };
144	
145	/**
146	 * Why "Change folder…" (relocate) did not point a workspace at the picked folder. Relocating
147	 * never moves or copies files: it only says where the workspace now lives.
148	 */
149	export type WorkspaceRelocateRefusal =
150	  | "read-only"
151	  | "unknown"
152	  /** The user closed the folder picker, or a window answered Cancel to an unsaved editor. */
153	  | "cancelled"
154	  /** A recording or an export is writing into the active workspace (the LOCKED state). */
155	  | "recording"
156	  | "exporting"
157	  /** A group move is running (part 2): a folder cannot change under it. */
158	  | "moving"
159	  /** The picked path is not a folder. */
160	  | "not-a-folder"
161	  /** The folder's `identity.json` exists but cannot be read; it is never overwritten. */
162	  | "unreadable"
163	  /** Another workspace's identity is in that folder; `workspaceName` names it. */
164	  | "different"
165	  /** The folder is already registered as another workspace; `workspaceName` names it. */
166	  | "already-registered"
167	  /** `.kaipu/` is there (items' sidecars) but no workspace identity: not this workspace's folder. */
168	  | "has-items-no-identity"
169	  /** No `.kaipu` at all: an empty or plain folder. Never adopted silently. */
170	  | "not-a-workspace"
171	  /** The registry could not store the new path. */
172	  | "not-writable";
173	
