175	export type WorkspaceRelocateResult =
176	  | {
177	      ok: true;
178	      workspace: WorkspaceView;
179	      /** The picked folder is the one it already points at: nothing changed, so no "now points" toast. */
180	      unchanged?: true;
181	    }
182	  | {
183	      ok: false;
184	      reason: WorkspaceRelocateRefusal;
185	      /** The other workspace, for `different` and `already-registered`. */
186	      workspaceName?: string;
187	    };
188	
189	export type WorkspaceRemoveResult =
190	  | { ok: true }
191	  | { ok: false; reason: "active" | "last" | "unknown" | "read-only" };
192	
193	/** Main → window `workspaces:prepare`: flush, ask about unsaved work, close editors. */
194	export interface WorkspacePrepareRequest {
195	  requestId: number;
196	}
