199	export interface WorkspacePrepareResult {
200	  requestId: number;
201	  ok: boolean;
202	}
203	
204	/** The message main rejects a stale item-scoped call with (ADR 0032, decision 6). */
205	export const STALE_WORKSPACE = "stale-workspace";
206	
207	/** Why an item stayed where it was (ADR 0033): nothing of it changed in either workspace. */
208	export type MoveRefusal =
209	  /** No media for that id (moved, renamed or deleted meanwhile), or another item holds it now. */
210	  | "not-found"
211	  /** The item's record cannot be read (NIW2-568): it is read-only until it reads again. */
212	  | "metadata-issue"
213	  /** A recording or an export is writing: moves wait for it. */
214	  | "busy"
215	  /** The destination is not connected, not writable, or its folder holds another workspace. */
216	  | "target-unavailable"
217	  /** The item is already in that workspace. */
218	  | "same-workspace"
219	  /** The item was dragged out less than 10 seconds ago: the drop may still be reading it. */
220	  | "dragged-just-now"
221	  /** The destination drive has no room for a copy. */
222	  | "no-room"
223	  /** The destination already holds this very item (a copied folder). */
224	  | "already-there"
225	  /** The destination's tag list cannot be read; moving would lose the item's tags. */
226	  | "tags-unreadable"
227	  /** The copy did not match the original byte for byte; the original is untouched. */
228	  | "checksum-mismatch"
229	  /** "Check and fix files" is running. */
230	  | "maintenance"
231	  /** The window's workspace is no longer the active one. */
232	  | "stale"
233	  /** A file operation failed; the original is untouched. */
234	  | "io";
235	
