237	export interface MoveItemRef {
238	  id: string;
239	  assetId: string;
240	}
241	
242	export interface MoveItemsRequest {
243	  items: MoveItemRef[];
244	  targetId: string;
245	}
246	
247	/** `workspaces:move-items`: a group of single moves, run one after another (ADR 0033, decision 14). */
248	export interface MoveItemsResult {
249	  targetId: string;
250	  moved: { id: string; newId: string }[];
251	  failed: { id: string; reason: MoveRefusal }[];
252	  /**
253	   * Not started because the user pressed Stop. A group refused as a whole (busy, stale,
254	   * maintenance) lists every item in `failed` with that reason and leaves this empty.
255	   */
256	  skipped: string[];
257	}
258	
