1	import { stat } from "node:fs/promises";
2	import { dirname, join } from "node:path";
3	import { app, BrowserWindow, dialog, ipcMain, shell } from "electron";
4	import { createMainTranslator } from "@kaipu/i18n/main";
5	import { IPC_CHANNELS } from "@shared/types";
6	import type {
7	  LocationCheck,
8	  MoveItemRef,
9	  MoveItemsResult,
10	  WorkspaceBusy,
11	  WorkspaceAddResult,
12	  WorkspaceCreateResult,
13	  WorkspaceEditResult,
14	  WorkspaceRelocateResult,
15	  WorkspacePrepareResult,
16	  WorkspaceRemoveResult,
17	  WorkspacesState,
18	  WorkspaceStamp,
19	  WorkspaceSwitchResult,
20	  WorkspaceView,
21	} from "@shared/types/workspaces";
22	import { getAppSettings } from "../infrastructure/settings-store";
23	import { dragLedger } from "../library/drag-ledger";
24	import { LibraryVault } from "../library/library-vault";
25	import { loadDeviceId } from "../library/tag-repository";
26	import { vaultActivity } from "../library/vault-activity";
27	import { refusalOfError, runMoveGroup } from "./move-group";
28	import { healMoves, moveItem, type MoveSide } from "./move-item";
29	import { uuidv7 } from "../library/tag-repository";
30	import { defaultVaultDirectory, forgetCachedPreferences } from "../library/vault-location";
31	import { StaleWorkspaceError, WorkspaceGate } from "./gate";
32	import { WorkspaceRegistry, type WorkspaceEntry } from "./registry";
33	import { PrepareRequests } from "./prepare-windows";
34	import { relocateRefusal, relocateWorkspace } from "./relocate";
35	import { switchWorkspace, type ActiveTransactionDeps } from "./switch-transaction";
36	import { APP_TITLE, composeWindowTitle } from "./window-title";
37	import { toWorkspaceView } from "./workspace-view";
38	
39	/**
40	 * Workspaces in the main process (ADR 0032): the registry, the gate every item-scoped call
41	 * runs through, and the switch transaction with its IPC. `initWorkspaces()` runs once in
42	 * `app.whenReady`, before any window exists, so the preload can read the stamp at load.
43	 */
44	
45	/** How long a window may take to prepare (an unsaved editor waits on the user's answer). */
46	const PREPARE_TIMEOUT_MS = 120_000;
47	
48	let registry: WorkspaceRegistry | null = null;
49	let gate: WorkspaceGate | null = null;
50	
51	export interface WorkspaceHost {
52	  /** What is writing into the active workspace (the switch lock). A move is added here. */
53	  busy(): "recording" | "exporting" | null;
54	  /** Dismiss the capture toast and drop the retained quiet-capture bytes. */
55	  dropPendingCaptures(): void;
56	  /** Re-list every window's library (`library:changed`). */
57	  broadcastLibraryChanged(): void;
58	}
59	
60	let host: WorkspaceHost | null = null;
61	
62	/** The group move running now, if any: it holds the switch lock from its first item to its last. */
63	let moveRun: { stop: boolean } | null = null;
64	
65	/** What locks the switcher right now. */
66	function busyNow(): WorkspaceBusy | null {
67	  return host?.busy() ?? (moveRun ? "moving" : null);
68	}
69	
70	function requireRegistry(): WorkspaceRegistry {
71	  if (!registry) throw new Error("workspaces: not initialized");
72	  return registry;
73	}
74	
75	export function workspaceGate(): WorkspaceGate {
76	  if (!gate) throw new Error("workspaces: not initialized");
77	  return gate;
78	}
79	
80	export async function initWorkspaces(): Promise<void> {
81	  registry = await WorkspaceRegistry.open({
82	    preferencesFile: join(app.getPath("userData"), "preferences.json"),
83	    defaultDirectory: defaultVaultDirectory(),
84	    newId: () => uuidv7(),
85	    onPreferencesWritten: forgetCachedPreferences,
86	  });
87	  gate = new WorkspaceGate(registry.active().id);
88	  // The preload reads the stamp once, synchronously, before the page's scripts run, so it
89	  // is answered from here, before any window can exist.
90	  ipcMain.on(IPC_CHANNELS.workspacesStampSync, (event) => {
91	    event.returnValue = workspaceGate().stamp satisfies WorkspaceStamp;
92	  });
93	  if (registry.readOnly) {
94	    console.warn("[workspaces] preferences.json does not parse: running read-only until restart");
95	  }
96	  // A move the app died in is finished before anything lists either workspace.
97	  await healPendingMoves();
98	}
99	
100	function movesJournalDir(): string {
101	  return join(app.getPath("userData"), "workspace-moves");
102	}
103	
104	/** The folder a workspace of a move lives in now, or null while it is not connected. */
105	async function resolveMoveSide(side: MoveSide): Promise<string | null> {
106	  const reg = requireRegistry();
107	  if (!reg.get(side.workspaceId)) return null;
108	  const { availability, id } = await reg.availability(side.workspaceId);
109	  if (availability.state !== "available") return null;
110	  return reg.get(id)?.path ?? null;
111	}
112	
113	/**
114	 * Finish every move the app died in (ADR 0033, decision 6). At startup and before each group.
115	 * An entry whose workspace is not connected waits for a later run.
116	 */
117	async function healPendingMoves(): Promise<void> {
118	  try {
119	    const report = await healMoves({ journalDir: movesJournalDir(), resolve: resolveMoveSide });
120	    if (report.healed > 0) host?.broadcastLibraryChanged();
121	    if (report.quarantined.length > 0) {
122	      console.error(
123	        `[workspaces] ${report.quarantined.length} interrupted move(s) need a look; journal kept in`,
124	        movesJournalDir(),
125	      );
126	    }
127	  } catch (error) {
128	    console.error("[workspaces] healing interrupted moves failed", error);
129	  }
130	}
131	
132	let deviceId: Promise<string> | null = null;
133	
134	/**
135	 * `workspaces:move-items`: a group of single moves from the active workspace to `targetId`,
136	 * one after another (ADR 0033, decision 14). Runs inside the workspace gate, so the window's
137	 * stamp must still be current, and holds the switch lock from the first item to the last.
138	 */
139	async function moveItems(
140	  sender: Electron.WebContents,
141	  stamp: unknown,
142	  input: unknown,
143	): Promise<MoveItemsResult> {
144	  const reg = requireRegistry();
145	  const { items: rawItems, targetId } = (input ?? {}) as { items?: unknown; targetId?: unknown };
146	  const items: MoveItemRef[] = Array.isArray(rawItems)
147	    ? rawItems.filter(
148	        (item): item is MoveItemRef =>
149	          !!item &&
150	          typeof (item as MoveItemRef).id === "string" &&
151	          typeof (item as MoveItemRef).assetId === "string",
152	      )
153	    : [];
154	  const target = typeof targetId === "string" ? targetId : "";
155	  const refuseAll = (reason: MoveItemsResult["failed"][number]["reason"]): MoveItemsResult => ({
156	    targetId: target,
157	    moved: [],
158	    failed: items.map((item) => ({ id: item.id, reason })),
159	    skipped: [],
160	  });
161	  if (moveRun) return refuseAll("busy");
162	  if (!workspaceGate().isCurrent(stamp)) return refuseAll("stale");
163	  if (vaultActivity.inMaintenance) return refuseAll("maintenance");
164	
165	  const run = { stop: false };
166	  moveRun = run;
167	  void broadcastState();
168	  try {
169	    return await workspaceGate().run(stamp, () =>
170	      vaultActivity.run("library", async () => {
171	        await healPendingMoves();
172	        const source = reg.active();
173	        // A rejected read is not kept: the next group asks again.
174	        deviceId ??= loadDeviceId(app.getPath("userData")).catch((error: unknown) => {
175	          deviceId = null;
176	          throw error;
177	        });
178	        const device = await deviceId;
179	        const result = await runMoveGroup(
180	          items,
181	          async (item) => {
182	            // Checked per item, when its turn comes (decision 14).
183	            if (host?.busy()) return { ok: false, reason: "busy" };
184	            if (target === source.id) return { ok: false, reason: "same-workspace" };
185	            const entry = reg.get(target);
186	            if (!entry) return { ok: false, reason: "target-unavailable" };
187	            const directory = await resolveMoveSide({ workspaceId: target, directory: "" });
188	            if (directory === null) return { ok: false, reason: "target-unavailable" };
189	            const outcome = await moveItem(
190	              {
191	                source: { workspaceId: source.id, directory: source.path },
192	                target: { workspaceId: target, directory },
193	                id: item.id,
194	                expectedAssetId: item.assetId,
195	              },
196	              { journalDir: movesJournalDir(), deviceId: () => device, dragLedger },
197	            );
198	            return outcome.ok
199	              ? { ok: true, newId: outcome.newId }
200	              : { ok: false, reason: outcome.reason };
201	          },
202	          {
203	            targetId: target,
204	            stopped: () => run.stop,
205	            onProgress: (progress) => {
206	              if (!sender.isDestroyed()) {
207	                sender.send(IPC_CHANNELS.workspacesMoveProgress, progress);
208	              }
209	            },
210	          },
211	        );
212	        return result;
213	      }),
214	    );
215	  } catch (error) {
216	    console.error("[workspaces] group move refused", error);
217	    return refuseAll(refusalOfError(error));
218	  } finally {
219	    moveRun = null;
220	    host?.broadcastLibraryChanged();
221	    void broadcastState();
222	  }
223	}
224	
225	export function activeWorkspace(): WorkspaceEntry {
226	  return requireRegistry().active();
227	}
228	
229	/** Owns the cloud entries without a workspace id (spec decision 3): only it lists them. */
230	export function ownsLegacyCloud(): boolean {
231	  const reg = requireRegistry();
232	  return reg.active().id === reg.state.legacyCloudOwnerId;
233	}
234	
235	/** The workspace's name for a label, only once a second one exists (window title, tray). */
236	function prefixName(): string | null {
237	  const reg = requireRegistry();
238	  return reg.entries().length > 1 ? reg.active().name : null;
239	}
240	
241	/** The capture target was unplugged or replaced: refuse, never save anywhere else. */
242	export class WorkspaceNotConnectedError extends Error {
243	  constructor(readonly workspaceName: string) {
244	    const t = createMainTranslator(getAppSettings().locale);
245	    super(t("workspaces.notConnectedError", { name: workspaceName }));
246	    this.name = "WorkspaceNotConnectedError";
247	  }
248	}
249	
250	/**
251	 * The active workspace, checked to be connected, for a capture that is about to start.
252	 * Throws `WorkspaceNotConnectedError` otherwise; a switch in progress counts as stale.
253	 */
254	export async function requireCaptureWorkspace(): Promise<WorkspaceEntry> {
255	  const reg = requireRegistry();
256	  if (workspaceGate().switching) throw new StaleWorkspaceError();
257	  const active = reg.active();
258	  const { availability, id } = await reg.availability(active.id);
259	  if (workspaceGate().adopt(active.id, id, reg.active().id)) void broadcastState();
260	  if (availability.state !== "available") throw new WorkspaceNotConnectedError(active.name);
261	  return reg.active();
262	}
263	
264	/** Every workspace whose folder is reachable, for the startup and quit sweeps. */
265	export async function availableWorkspacePaths(): Promise<string[]> {
266	  const reg = requireRegistry();
267	  const paths: string[] = [];
268	  // A copy: a probe may update an entry (a pending one adopting its folder's id).
269	  for (const entry of reg.entries().slice()) {
270	    const { availability } = await reg.availability(entry.id);
271	    if (availability.state === "available") paths.push(entry.path);
272	  }
273	  return paths;
274	}
275	
276	async function listState(): Promise<WorkspacesState> {
277	  const reg = requireRegistry();
278	  const views: WorkspaceView[] = [];
279	  for (const entry of reg.entries().slice()) {
280	    const { availability, id } = await reg.availability(entry.id);
281	    // A pending active entry that adopted its folder's id: windows must take the new stamp.
282	    if (workspaceGate().adopt(entry.id, id, reg.active().id)) void broadcastState();
283	    const count =
284	      availability.state === "available"
285	        ? await new LibraryVault(entry.path).countMedia().catch(() => null)
286	        : null;
287	    // Which volume the folder is on: "Move to" says whether a move copies or is instant.
288	    const device =
289	      availability.state === "available"
290	        ? await stat(entry.path).then(
291	            (info) => String(info.dev),
292	            () => null,
293	          )
294	        : null;
295	    views.push(toWorkspaceView(reg.get(id) ?? entry, availability, count, device));
296	  }
297	  const { activeId, hintDismissedAt } = reg.state;
298	  return {
299	    activeId,
300	    generation: workspaceGate().stamp.generation,
301	    hintDismissed: hintDismissedAt !== undefined,
302	    busy: busyNow(),
303	    readOnly: reg.readOnly,
304	    workspaces: views,
305	  };
306	}
307	
308	function sendToAll(channel: string, payload?: unknown): void {
309	  for (const window of BrowserWindow.getAllWindows()) {
310	    if (!window.isDestroyed()) window.webContents.send(channel, payload);
311	  }
312	}
313	
314	async function broadcastState(): Promise<void> {
315	  sendToAll(IPC_CHANNELS.workspacesChanged, await listState());
316	}
317	
318	/** The main window's title follows the active workspace and the page's own title. */
319	export function attachWindowTitle(window: BrowserWindow): void {
320	  let pageTitle = APP_TITLE;
321	  const apply = (): void => {
322	    if (!window.isDestroyed()) window.setTitle(composeWindowTitle(pageTitle, prefixName()));
323	  };
324	  window.on("page-title-updated", (event, title) => {
325	    event.preventDefault();
326	    pageTitle = title;
327	    apply();
328	  });
329	  titleAppliers.add(apply);
330	  window.on("closed", () => titleAppliers.delete(apply));
331	  apply();
332	}
333	
334	const titleAppliers = new Set<() => void>();
335	
336	function refreshTitles(): void {
337	  for (const apply of titleAppliers) apply();
338	}
339	
340	const prepareRequests = new PrepareRequests(IPC_CHANNELS.workspacesPrepare, PREPARE_TIMEOUT_MS);
341	
342	/** What every change to the active workspace shares: the lock, the windows, the commit. */
343	function activeTransactionDeps(): ActiveTransactionDeps {
344	  return {
345	    gate: workspaceGate(),
346	    // The group move holds this lock too: a folder cannot change under it.
347	    busy: busyNow,
348	    prepareWindows: () => prepareRequests.prepare(BrowserWindow.getAllWindows()),
349	    abortWindows: () => sendToAll(IPC_CHANNELS.workspacesPrepareAbort),
350	    dropPendingCaptures: () => host?.dropPendingCaptures(),
351	    afterCommit: () => {
352	      refreshTitles();
353	      void broadcastState();
354	      host?.broadcastLibraryChanged();
355	    },
356	  };
357	}
358	
359	async function runSwitch(id: string): Promise<WorkspaceSwitchResult> {
360	  const reg = requireRegistry();
361	  const result = await switchWorkspace(
362	    {
363	      ...activeTransactionDeps(),
364	      activeId: () => reg.active().id,
365	      isKnown: (candidate) => reg.get(candidate) !== undefined,
366	      readOnly: () => reg.readOnly,
367	      availability: (candidate) => reg.availability(candidate),
368	      persistActive: (target) => reg.setActive(target),
369	    },
370	    id,
371	  );
372	  // A refused switch still re-lists, so a LOCKED or NOT CONNECTED menu shows why.
373	  if (!result.ok) void broadcastState();
374	  return result;
375	}
376	
377	/** Folder picker for Add workspace; initializes or adopts the folder, then switches to it. */
378	async function addWorkspace(
379	  sender: Electron.WebContents,
380	  request: { activate?: unknown } = {},
381	): Promise<WorkspaceAddResult> {
382	  const reg = requireRegistry();
383	  if (reg.readOnly) return { ok: false, reason: "read-only" };
384	  const window = BrowserWindow.fromWebContents(sender);
385	  const t = createMainTranslator(getAppSettings().locale);
386	  const options: Electron.OpenDialogOptions = {
387	    title: t("dialogs.addWorkspace"),
388	    buttonLabel: t("dialogs.addWorkspaceButton"),
389	    properties: ["openDirectory", "createDirectory"],
390	  };
391	  const picked = window
392	    ? await dialog.showOpenDialog(window, options)
393	    : await dialog.showOpenDialog(options);
394	  const chosen = picked.filePaths[0];
395	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
396	
397	  const outcome = await reg.add(chosen);
398	  if (!outcome.ok) {
399	    if (outcome.reason !== "read-only") {
400	      const message = { type: "error" as const, message: t("dialogs.folderUnusable") };
401	      const detail = t(
402	        outcome.reason === "unreadable"
403	          ? "dialogs.workspaceUnreadableDetail"
404	          : "dialogs.folderUnusableDetail",
405	      );
406	      await (window
407	        ? dialog.showMessageBox(window, { ...message, detail })
408	        : dialog.showMessageBox({ ...message, detail }));
409	    }
410	    return { ok: false, reason: outcome.reason === "read-only" ? "read-only" : "not-writable" };
411	  }
412	  // Adding a workspace answers the "New: workspaces" hint too.
413	  await reg.dismissHint();
414	  const { availability } = await reg.availability(outcome.entry.id);
415	  // Then make it the active one, through the same transaction as any other switch. A
416	  // refusal (a recording running) leaves it registered and inactive. "Move to ▸ New
417	  // workspace…" keeps it inactive: the item goes there, the user stays here.
418	  if (request.activate !== false) await runSwitch(outcome.entry.id);
419	  await broadcastState();
420	  return { ok: true, workspace: toWorkspaceView(outcome.entry, availability, null) };
421	}
422	
423	/**
424	 * New workspace: a new folder next to the Default workspace's, only Kaipu's files in it, then
425	 * the same switch as any other. A refused switch (a recording running) leaves it registered.
426	 */
427	async function createWorkspace(input: unknown): Promise<WorkspaceCreateResult> {
428	  const reg = requireRegistry();
429	  const { name, color, activate } = (input ?? {}) as {
430	    name?: unknown;
431	    color?: unknown;
432	    activate?: unknown;
433	  };
434	  if (typeof name !== "string") return { ok: false, reason: "invalid-name" };
435	  if (typeof color !== "string") return { ok: false, reason: "invalid-color" };
436	  const outcome = await reg.create({ name, color });
437	  if (!outcome.ok) return outcome;
438	  await reg.dismissHint();
439	  const { availability } = await reg.availability(outcome.entry.id);
440	  // "Move to ▸ New workspace…" creates it inactive: the item goes there, the user stays here.
441	  const switchResult: WorkspaceSwitchResult =
442	    activate === false ? { ok: true } : await runSwitch(outcome.entry.id);
443	  await broadcastState();
444	  return {
445	    ok: true,
446	    workspace: toWorkspaceView(outcome.entry, availability, null),
447	    switchResult,
448	  };
449	}
450	
451	async function editWorkspace(input: unknown): Promise<WorkspaceEditResult> {
452	  const reg = requireRegistry();
453	  const { id, name, color } = (input ?? {}) as { id?: unknown; name?: unknown; color?: unknown };
454	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
455	  const outcome = await reg.edit(id, {
456	    ...(typeof name === "string" ? { name } : {}),
457	    ...(typeof color === "string" ? { color } : {}),
458	  });
459	  if (!outcome.ok) return outcome;
460	  const { availability } = await reg.availability(outcome.entry.id);
461	  // The window title shows the active workspace's name, and the tiles show the initials.
462	  refreshTitles();
463	  await broadcastState();
464	  return {
465	    ok: true,
466	    workspace: toWorkspaceView(outcome.entry, availability, null),
467	    savedToFolder: outcome.savedToFolder,
468	  };
469	}
470	
471	/**
472	 * "Change folder…": the native folder picker, then the workspace is pointed at that folder.
473	 * Relocating never moves or copies files; the rules are in `relocate.ts` and the registry.
474	 */
475	async function relocateFolder(
476	  sender: Electron.WebContents,
477	  id: unknown,
478	): Promise<WorkspaceRelocateResult> {
479	  const reg = requireRegistry();
480	  const deps = { ...activeTransactionDeps(), registry: reg };
481	  if (typeof id !== "string") return { ok: false, reason: "unknown" };
482	  // Locked or read-only: say so now, instead of after the user picked a folder.
483	  const refused = relocateRefusal(deps, id);
484	  if (refused) return refused;
485	  const entry = reg.get(id);
486	  if (!entry) return { ok: false, reason: "unknown" };
487	
488	  const window = BrowserWindow.fromWebContents(sender);
489	  const t = createMainTranslator(getAppSettings().locale);
490	  const options: Electron.OpenDialogOptions = {
491	    title: t("dialogs.relocateWorkspace", { name: entry.name }),
492	    buttonLabel: t("dialogs.relocateWorkspaceButton"),
493	    // Where it was: a moved folder is usually next to where it used to be.
494	    defaultPath: dirname(entry.path),
495	    properties: ["openDirectory", "createDirectory"],
496	  };
497	  const picked = window
498	    ? await dialog.showOpenDialog(window, options)
499	    : await dialog.showOpenDialog(options);
500	  const chosen = picked.filePaths[0];
501	  if (picked.canceled || !chosen) return { ok: false, reason: "cancelled" };
502	
503	  const outcome = await relocateWorkspace(deps, id, chosen);
504	  if (!outcome.ok) return outcome;
505	  const { availability } = await reg.availability(outcome.entry.id);
506	  // The active workspace re-lists inside its transaction; any other one only needs the state.
507	  refreshTitles();
508	  await broadcastState();
509	  return {
510	    ok: true,
511	    workspace: toWorkspaceView(reg.get(outcome.entry.id) ?? outcome.entry, availability, null),
512	    ...(outcome.unchanged ? { unchanged: true as const } : {}),
513	  };
514	}
515	
516	export function registerWorkspaceHandlers(deps: WorkspaceHost): void {
517	  host = deps;
518	  ipcMain.handle(IPC_CHANNELS.workspacesList, () => listState());
519	  ipcMain.handle(IPC_CHANNELS.workspacesSwitch, (_event, id: unknown) =>
520	    typeof id === "string" ? runSwitch(id) : { ok: false, reason: "unknown" },
521	  );
522	  ipcMain.handle(IPC_CHANNELS.workspacesAdd, (event, options: unknown) =>
523	    addWorkspace(event.sender, (options ?? {}) as { activate?: unknown }),
524	  );
525	  ipcMain.handle(IPC_CHANNELS.workspacesMoveItems, (event, stamp: unknown, input: unknown) =>
526	    moveItems(event.sender, stamp, input),
527	  );
528	  ipcMain.handle(IPC_CHANNELS.workspacesCancelMove, () => {
529	    if (moveRun) moveRun.stop = true;
530	  });
531	  ipcMain.handle(IPC_CHANNELS.workspacesCreate, (_event, input: unknown) => createWorkspace(input));
532	  ipcMain.handle(IPC_CHANNELS.workspacesEdit, (_event, input: unknown) => editWorkspace(input));
533	  ipcMain.handle(IPC_CHANNELS.workspacesRelocate, (event, id: unknown) =>
534	    relocateFolder(event.sender, id),
535	  );
536	  ipcMain.handle(
537	    IPC_CHANNELS.workspacesCheckLocation,
538	    (_event, name: unknown): Promise<LocationCheck> =>
539	      typeof name === "string"
540	        ? requireRegistry().checkNewLocation(name)
541	        : Promise.resolve({ path: null, state: "parent-missing" }),
542	  );
543	  ipcMain.handle(
544	    IPC_CHANNELS.workspacesRemove,
545	    async (_event, id: unknown): Promise<WorkspaceRemoveResult> => {
546	      if (typeof id !== "string") return { ok: false, reason: "unknown" };
547	      const result = await requireRegistry().remove(id);
548	      if (result.ok) {
549	        refreshTitles();
550	        await broadcastState();
551	      }
552	      return result;
553	    },
554	  );
555	  ipcMain.handle(IPC_CHANNELS.workspacesOpenFolder, async (_event, id: unknown) => {
556	    const entry = typeof id === "string" ? requireRegistry().get(id) : undefined;
557	    if (!entry) return;
558	    // shell.openPath never creates the folder: a missing one reports an error string.
559	    const error = await shell.openPath(entry.path);
560	    if (error) console.error("failed to open the workspace folder", error);
561	  });
562	  ipcMain.handle(IPC_CHANNELS.workspacesDismissHint, async () => {
563	    await requireRegistry().dismissHint();
564	    await broadcastState();
565	  });
566	  ipcMain.on(IPC_CHANNELS.workspacesPrepareResult, (_event, result: WorkspacePrepareResult) => {
567	    if (!result || typeof result.requestId !== "number") return;
568	    prepareRequests.answer(result.requestId, result.ok === true);
569	  });
570	}
571	
572	/** Re-list the switcher in every window (the lock changed: a take started or ended). */
573	export function notifyWorkspaceBusyChanged(): void {
574	  if (registry && gate) void broadcastState();
575	}
